  function teamMenu(rs){return `<div class="laff-rk-team-filter"><button type="button" class="laff-rk-select laff-rk-team-toggle"><span>${esc(teamText())}</span><b>▾</b></button><div id="laff-kills-team-menu" class="laff-rk-menu"><button type="button" class="laff-rk-close">Fechar ×</button><label class="laff-rk-all"><input type="checkbox" class="laff-rk-all-check" ${teams.has("__all")?"checked":""}> <span>Selecionar tudo</span></label>${teamOptions(rs).map(([k,n])=>`<div class="laff-rk-team-row"><label><input type="checkbox" class="laff-rk-team-check" data-team="${esc(k)}" ${teams.has("__all")||teams.has(k)?"checked":""}> <span>${esc(n)}</span></label><button type="button" class="laff-rk-only" data-team="${esc(k)}">SOMENTE</button></div>`).join("")}</div></div>`}
