  function openPlayer(name){const n=String(name||"").trim(); if(!n)return; if(typeof window.openLAFFPlayerProfile==="function")return window.openLAFFPlayerProfile(n); if(typeof window.showPlayerProfile==="function")return window.showPlayerProfile(n); location.hash=n.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"")}
  function bind(root){root.querySelector(".laff-rk-team-toggle")?.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();root.querySelector("#laff-kills-team-menu")?.classList.toggle("is-open")}); root.querySelector(".laff-rk-close")?.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();root.querySelector("#laff-kills-team-menu")?.classList.remove("is-open")}); root.querySelector(".laff-rk-all-check")?.addEventListener("change",e=>{teams=e.target.checked?new Set(["__all"]):new Set; render()}); root.querySelectorAll(".laff-rk-team-check").forEach(cb=>cb.addEventListener("change",e=>{teams.delete("__all"); e.target.checked?teams.add(e.target.dataset.team):teams.delete(e.target.dataset.team); if(!teams.size)teams.add("__all"); render()})); root.querySelectorAll(".laff-rk-only").forEach(btn=>btn.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();teams=new Set([e.currentTarget.dataset.team]); render()})); root.querySelector(".laff-rk-stage")?.addEventListener("change",e=>{stage=e.target.value; render()}); root.querySelector(".laff-rk-position")?.addEventListener("change",e=>{position=e.target.value; render()}); root.querySelectorAll(".laff-player-link").forEach(btn=>btn.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();openPlayer(e.currentTarget.dataset.player)}))}
  async function render(){const root=document.getElementById("laff-mvp-content"), active=document.querySelector(".page.active")?.id; if(!root||active!=="laff-mvp")return; root.innerHTML=hero()+`<section class="laff-panel"><div class="laff-empty">Carregando ranking...</div></section>`; const all=await rows(), list=filtered(all); root.innerHTML=hero()+`<section class="laff-panel laff-kills-panel"><div class="laff-section-head"><div><h2>Ranking MVP</h2></div></div><div class="laff-rk-filters"><div class="laff-rk-field"><label>Etapa:</label><select class="laff-rk-select laff-rk-stage"><option value="geral" ${stage==="geral"?"selected":""}>Geral</option><option value="classificatoria" ${stage==="classificatoria"?"selected":""}>Classificatória</option><option value="final" ${stage==="final"?"selected":""}>Final</option></select></div><div class="laff-rk-field"><label>Equipe:</label>${teamMenu(all)}</div><div class="laff-rk-field"><label>Posição:</label>${posFilter()}</div></div>${list.length?`<div class="table-container"><table class="laff-table laff-kills-table"><thead><tr><th>#</th><th><span class="laff-head-full">Jogador</span><span class="laff-head-short">J</span></th><th><span class="laff-head-full">Equipe</span><span class="laff-head-short">E</span></th><th><span class="laff-head-full">Abates</span><span class="laff-head-short">K</span></th><th><span class="laff-head-full">Quedas</span><span class="laff-head-short">Q</span></th><th>MdK</th></tr></thead><tbody>${list.map((r,i)=>`<tr><td>${i+1}</td><td class="laff-kills-player"><button type="button" class="laff-player-link" data-player="${esc(r.jogador)}">${esc(r.jogador)}</button></td><td class="laff-table-team"><img src="${esc(logo(r.equipe))}" onerror="this.src='escudo.webp'" alt=""> <span class="laff-team-name-full">${esc(r.equipe)}</span><span class="laff-team-name-short">${esc(shortTeam(r.equipe))}</span></td><td>${r.abates}</td><td>${r.quedas}</td><td>${r.media.toFixed(2).replace(".",",")}</td></tr>`).join("")}</tbody></table></div>`:`<div class="laff-empty">${stage==="final"?"A tabela da Final será exibida quando os dados forem cadastrados.":"Nenhum jogador encontrado com os filtros selecionados."}</div>`}</section>`; bind(root)}
